/**
 * @summary List saved library items
 */
export const getListLibraryItemsUrl = (params?: ListLibraryItemsParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/library?${stringifiedParams}`
    : `/api/library`;
};

export const listLibraryItems = async (
  params?: ListLibraryItemsParams,
  options?: RequestInit,
): Promise<LibraryItem[]> => {
  return customFetch<LibraryItem[]>(getListLibraryItemsUrl(params), {
    ...options,
    method: "GET",
  });
};

